% lemmas.tex -- proof-trails: what can be proven about HighwayHash-64 collisions.
% Notation.  Words live in $\mathbb Z/2^{64}$; $\lo(x)=x \bmod 2^{32}$, $\hi(x)=\lfloor x/2^{32}\rfloor$,
% $\sigma(x)=2^{32}\lo(x)+\hi(x)$ (half swap), byte $k$ of $x$ = bits $8k..8k+7$.  A state is
% $S=(v_0,v_1,m_0,m_1)\in(\mathbb Z/2^{64})^{4\times 4}$ (the reference's v0, v1, mul0, mul1), lane $i\in\{0,1,2,3\}$,
% pairs $\{0,1\}$ and $\{2,3\}$; in a pair $(a,b)$ the lane $a$ is the even one.
\newcommand{\lo}{\operatorname{lo}}\newcommand{\hi}{\operatorname{hi}}
\newcommand{\Upd}{\mathrm{Update}}\newcommand{\Zip}{Z}

\paragraph{The primitive.}
For a packet $p=(p_0,\dots,p_3)$, $\Upd_p$ acts on $S$ by, for each lane $i$,
\begin{align*}
&\text{(A)}\; v_{1,i}\gets v_{1,i}+m_{0,i}+p_i,\qquad
 \text{(B)}\; m_{0,i}\gets m_{0,i}\oplus \lo(v_{1,i})\cdot\hi(v_{0,i}),\\
&\text{(C)}\; v_{0,i}\gets v_{0,i}+m_{1,i},\qquad\qquad
 \text{(D)}\; m_{1,i}\gets m_{1,i}\oplus \lo(v_{0,i})\cdot\hi(v_{1,i}),
\end{align*}
followed, for each pair $(a,b)$, by
(E) $v_{0,a}\gets v_{0,a}+\Zip_a(v_{1,a},v_{1,b})$, $v_{0,b}\gets v_{0,b}+\Zip_b(v_{1,a},v_{1,b})$ and
(F) $v_{1,a}\gets v_{1,a}+\Zip_a(v_{0,a},v_{0,b})$, $v_{1,b}\gets v_{1,b}+\Zip_b(v_{0,a},v_{0,b})$,
where the ZipperMerge addends are the byte rearrangements (read off \texttt{ZipperMergeAndAdd}; output bytes $0,\dots,7$)
\[
\Zip_a(x,y)=[x_3,\,y_4,\,x_2,\,x_5,\,y_6,\,x_1,\,y_7,\,x_0],\qquad
\Zip_b(x,y)=[y_3,\,x_4,\,y_2,\,y_5,\,y_1,\,x_6,\,y_0,\,x_7].
\]
The $32\times32\to64$ products in (B), (D) are exact integers.  Together $(\Zip_a,\Zip_b)$ is a permutation of the 16 bytes of $(x,y)$: lane $a$ receives its own bytes $\{0,1,2,3,5\}$ and the partner's bytes $\{4,6,7\}$, and symmetrically.
A finalization round is $\rho(S)=\Upd_{\pi(v_0)}(S)$ with $\pi(v_0)=(\sigma(v_{0,2}),\sigma(v_{0,3}),\sigma(v_{0,0}),\sigma(v_{0,1}))$; the output is $\tau(S)=v_{0,0}+v_{1,0}+m_{0,0}+m_{1,0}$;
$\mathrm{Reset}(k)$ sets $v_{0,i}=c_{0,i}\oplus k_i$, $v_{1,i}=c_{1,i}\oplus\sigma(k_i)$, $m_{0,i}=c_{0,i}$, $m_{1,i}=c_{1,i}$ with public $c_{0},c_{1}$; the remainder step $\mathrm{Rem}_s$ ($s=|M|\bmod 32\ne0$) adds $2^{32}s+s$ to every $v_{0,i}$, rotates both halves of every $v_{1,i}$ left by $s$, and applies $\Upd$ to the padded tail packet.
$\mathrm{HH}_R(k,M)=\tau\big(\rho^R(\mathrm{Abs}_M(\mathrm{Reset}(k)))\big)$; $R=4$ is HighwayHash-64.

\begin{lemma}[permutation; collisions are truncation collisions]\label{lem:perm}
For every packet $p$, $\Upd_p$ is a bijection of $(\mathbb Z/2^{64})^{16}$, with inverse
$F^{-1}$: $v_{1,\cdot}\gets v_{1,\cdot}-\Zip_\cdot(v_{0,a},v_{0,b})$;
$E^{-1}$: $v_{0,\cdot}\gets v_{0,\cdot}-\Zip_\cdot(v_{1,a},v_{1,b})$;
then per lane $D^{-1}$: $m_{1,i}\gets m_{1,i}\oplus\lo(v_{0,i})\hi(v_{1,i})$;
$C^{-1}$: $v_{0,i}\gets v_{0,i}-m_{1,i}$;
$B^{-1}$: $m_{0,i}\gets m_{0,i}\oplus\lo(v_{1,i})\hi(v_{0,i})$;
$A^{-1}$: $v_{1,i}\gets v_{1,i}-m_{0,i}-p_i$.
$\rho$ and $\mathrm{Rem}_s$ are bijections as well ($\rho^{-1}$ recovers the packet $\pi(v_0)$ after $C^{-1}$).
For messages $M\ne M'$ of equal length and every key $k$, the states $X=\rho^R(\mathrm{Abs}_M(\mathrm{Reset}(k)))$ and $X'$ differ; hence every collision $\mathrm{HH}_R(k,M)=\mathrm{HH}_R(k,M')$ is a collision of the truncation $\tau$ on two distinct states, and every fibre of $\tau$ has exactly $2^{960}$ states.
\end{lemma}
\begin{proof}
Each of (A)--(F) adds to, or XORs into, one coordinate a value computed from coordinates it does not modify, so each is a bijection and the displayed maps undo them in reverse order.  In $\rho$ the packet $\pi(v_0)$ is read from $v_0$, which (A) does not modify, so (A) is still such a transvection.  $\mathrm{Rem}_s$ composes a translation, a bit rotation and an $\Upd$.
For equal lengths the padded packet sequences of $M\ne M'$ differ (every message byte occupies a packet position: bytes $32q+j$ go to packet $q$, and the tail bytes go to positions $0..(s\,\&\,{\sim}3)-1$, $16..18$ or $28..31$ of the last packet, all of them injectively for a fixed $s$).  At the first differing packet the two executions start from the same state and (A) produces different $v_1$; the remaining steps, packets and rounds are bijections, so $X\ne X'$.  $\tau$ is a group homomorphism onto $\mathbb Z/2^{64}$, so its fibres are cosets of size $2^{1024-64}$.
\end{proof}

\begin{lemma}[lane locality; $R=0$]\label{lem:r0}
(i) In $\Upd_p$ the eight words of lanes $\{0,1\}$ after the step depend only on the eight words of lanes $\{0,1\}$ before it and on $p_0,p_1$; likewise for $\{2,3\}$ and $p_2,p_3$.  $\mathrm{Reset}$ and $\mathrm{Rem}_s$ act lane-wise, and the tail packet places tail bytes $j<\min(16,s\,\&\,{\sim}3)$ into lanes $0,1$ and every other tail byte into lanes $2,3$.  Hence $\mathrm{HH}_0(k,M)$ is a function of $k_0,k_1$, $|M|$, and the message bytes at positions $32q+j$, $0\le j<16$ (for the tail, $j<\min(16,s\,\&\,{\sim}3)$) only.
(ii) Consequently, at $R=0$ two messages of the same length that agree on those bytes collide for every key.  In particular any difference confined to lanes $2,3$ of any packets collides with probability~1, all $256$ one-byte messages collide, and the last $s\bmod 4$ bytes of a message with $1\le s\le 15$ are ignored.
(iii) The converse (only such differences collide with probability exactly~1) is not proven.  It was checked for the $128$ single-bit differences in lanes $0,1$ of a $32$-byte message: none collided for all of $2^{16}$ keys, but lane~1 bit~16 collided for $65533$ and bit~17 for $65535$ (second key stream: $65526$) of $65536$ keys.
(iv) Those near-certain cases are the carry-free part of the class: the lane-$0$ words after $\Upd$ receive lane-$1$ values only through bytes $4,6,7$ of $v_{1,1}$ (after (A), into $v_{0,0}$ at (E)) and bytes $4,6,7$ of $v_{0,1}$ (after (E), into $v_{1,0}$ at (F)); $m_{0,0},m_{1,0}$ read lane-$0$ words only.  Hence a last-packet difference confined to bytes $2,3,5$ of lane~$1$ (bits $16..31$, $40..47$) and to lanes $2,3$ leaves lane~$0$ untouched, and the $R=0$ outputs collide, unless the addition at (A) carries into byte $4$ or $6$ of $v_{1,1}$, or the addition at (E) carries into byte $4$, $6$ or $7$ of $v_{0,1}$ (the own bytes $2,3,5$ of $v_{1,1}$ land in bytes $2,0,3$ of the addend $\Zip_b$).  For a single flipped bit $b$ the carry model predicts a collision rate $(1-2^{-(32-b)})^2$ for $16\le b\le23$, $1-2^{-(32-b)}$ for $24\le b\le31$ and $(1-2^{-(48-b)})^2$ for $40\le b\le47$.
\end{lemma}
\begin{proof}
(A)--(D) act within a lane, (E)--(F) within a pair; the only cross-pair operation is $\pi$, which $R=0$ never applies; $\tau$ reads lane $0$.  The tail layout is read off \texttt{HighwayHashUpdateRemainder}: bytes $0..(s\,\&\,{\sim}3)-1$ are copied in place, the last $s\,\&\,3$ bytes go to packet bytes $16,17,18$ when $s<16$, and the last four message bytes are copied to packet bytes $28..31$ when $s\ge16$.  (iv) is the byte table of $\Zip_a,\Zip_b$: lane $a$ receives $b_4,b_6,b_7$ from its partner and nothing else.
\end{proof}
\noindent\emph{Checked} (\texttt{r0 20}, \texttt{active 16}; random base message and random key per trial): $32$-byte messages with random lanes $2,3$: $2^{20}/2^{20}$ collisions at $R=0$; $64$-byte messages differing in lanes $2,3$ of the first packet, or of both packets: $2^{20}/2^{20}$; all $256$ one-byte messages equal for $65536/65536$ keys; the $256$ values of byte $32$ of a $33$-byte message equal for $65536/65536$ keys; bytes $44..46$ of a $47$-byte message: $65536/65536$ (byte $43$ = packet byte $11$ = lane-$1$ bit $24$, a case of (iv): $65285$, carry model $65280$).  Every single bit of lanes $2,3$: $65536/65536$.  Single bits of lane~$1$, $2^{16}$ keys each, observed vs.\ the carry model: $b=16$: $65533$ vs $65534$; $b=23$: $65263$ vs $65280$; $b=24$: $65278$ vs $65280$; $b=28$: $61395$ vs $61440$; $b=31$: $33053$ vs $32768$; $b=40$: $65004$ vs $65025$; $b=44$: $57729$ vs $57600$; $b=47$: $16441$ vs $16384$.  All $64$ bits of lane~$0$ and the remaining $40$ bits of lane~$1$: $0/65536$.

\begin{lemma}[one-step separation]\label{lem:onestep}
Let two executions start from the same state and differ additively by $\delta=p_i'-p_i\ne0$ in lane $i$ of the packet.  After (A), $v_{1,i}'=v_{1,i}+\delta$; let $c\in\{0,1\}$ be the carry out of the low half, $c=[\lo(v_{1,i})+\lo(\delta)\ge 2^{32}]$.
\begin{enumerate}
\item[(a)] $\lo(v_{1,i}')\ne\lo(v_{1,i})$ iff $\lo(\delta)\ne0$.  $\hi(v_{1,i}')-\hi(v_{1,i})\equiv\hi(\delta)+c\pmod{2^{32}}$: the high halves differ always when $\hi(\delta)\notin\{0,2^{32}-1\}$, iff $c=1$ when $\hi(\delta)=0$, iff $c=0$ when $\hi(\delta)=2^{32}-1$.
\item[(b)] For $32$-bit $a\ne a'$ and $H$, $a'H-aH=(a'-a)H$ as integers, which vanishes iff $H=0$.  Hence with $H=\hi(v_{0,i})$ (not touched by (A)): $m_{0,i}'\ne m_{0,i}$ iff $\lo(\delta)\ne0$ and $H\ne0$.  With $L=\lo(v_{0,i}+m_{1,i})$ (the value after (C), equal in both executions): $m_{1,i}'\ne m_{1,i}$ iff $\hi(v_{1,i}')\ne\hi(v_{1,i})$ and $L\ne0$.
\item[(c)] For a one-packet message ($|M|\le32$, either path) and a uniform key: $v_{0,i}$ is a bijective image of $k_i$, so $H$ and $L=\lo(v_{0,i})+\lo(c_{1,i})\bmod2^{32}$ are independent uniform and $\Pr[H=0]=\Pr[L=0]=2^{-32}$, $\Pr[H=L=0]=2^{-64}$.  For $|M|=32$, $\lo(v_{1,i})=(\lo(c_{1,i})\oplus\hi(k_i))+\lo(c_{0,i}+p_i)\bmod2^{32}$ is uniform, so $\Pr[c=1]=\lo(\delta)/2^{32}$ exactly, and $c$ is independent of $L$ (a function of $\lo(k_i)$).
\end{enumerate}
In particular $m_{0,i}$ is unchanged for every key with $\hi(k_i)=\hi(c_{0,i})$, and $m_{1,i}$ for every key with $\lo(k_i)=\lo(c_{0,i})\oplus(-\lo(c_{1,i})\bmod 2^{32})$ (checked on $2^{16}$ keys of each subspace).
\end{lemma}
\begin{proof}
(a) is the addition with carry.  (b): the products are $<2^{64}$, so equality of $m\oplus aH$ and $m\oplus a'H$ is equality of the integers $aH$, $a'H$, i.e.\ $(a'-a)H=0$ in $\mathbb Z$.  (c): $x\mapsto c_{0,i}\oplus x$ and translations are bijections of $\mathbb Z/2^{64}$; the two halves of a uniform word are independent uniform.
\end{proof}
\noindent\emph{Checked} (\texttt{onestep 20}: $2^{20}$ keys per cell, lanes $0..3$ of a $32$-byte message, lane $0$ of an $8$-byte message (tail path, one packet) and lane $0$ of the tail of a $40$-byte message (two Updates, outside the lemma), ten $\delta$'s each, $60$ cells): in every cell $m_{0,i}$ changed exactly when $\lo(v_{1,i})$ changed and $m_{1,i}$ exactly when $\hi(v_{1,i})$ changed ($0$ mismatches), no co-operand $H_i$ or $L_i$ was $0$ ($2^{20}\cdot60$ draws, expected $0.03$), and the high-half rates matched (a): $\delta=2^{31}$: $0.4992$--$0.5005$ (pred.\ $0.5$); $\delta=2^{32}\!-\!1$: $1$; $\delta=-2^{31}$: $0.4994$--$0.5005$ (pred.\ $0.5$); $\delta=-2^{30}$: $0.2492$--$0.2503$ (pred.\ $0.25$); $\delta=1$: $0$; $\delta=2^{32}$: $1$.  (\texttt{cond 16}: $2^{16}$ keys per cell, lanes $0..3$) in the subspace $\hi(k_i)=\hi(c_{0,i})$, $m_{0,i}$ was unchanged for $65536/65536$ keys with $\delta=1$ and with $\delta=2^{31}$ (where $m_{1,i}$ changed for $32639$--$32937$ keys, the carry); in the subspace $\lo(k_i)=\lo(c_{0,i})\oplus(-\lo(c_{1,i}))$, $m_{1,i}$ was unchanged for $65536/65536$ keys with $\delta=2^{32}$ and with $\delta=2^{32}+1$ (where $m_{0,i}$ changed for all keys).

\begin{lemma}[silenced trails]\label{lem:silenced}
Call a multiply \emph{active} if one of its operands differs between the two executions, and call the pair of executions through $\Upd_p$ and $R$ rounds a \emph{silenced trail} if every active multiply has exactly one differing operand and its other operand is $0$.  On a silenced trail all $8(R+1)$ products coincide, so $m_0,m_1$ are equal throughout and the difference lives in $(v_0,v_1)$.  Let $J=\{i:\delta_i\ne0\}\ne\emptyset$ and $k_{\mathrm{msg}}(\delta)=\#\{i:\lo(\delta_i)\ne0\}+\#\{i:\hi(\delta_i)\notin\{0,2^{32}-1\}\}\ge|J|$.
\begin{enumerate}
\item[(a)] The message $\Upd$ activates at least $k_{\mathrm{msg}}(\delta)$ multiplies for every key, each with exactly one differing operand.  For a one-packet message the co-operands are independent uniform (Lemma~\ref{lem:onestep}(c)), so $\Pr[\text{message }\Upd\text{ silenced}]\le 2^{-32\,k_{\mathrm{msg}}(\delta)}$.
\item[(b)] On a silenced trail round~1 activates at least two multiplies, in two different lanes.
\item[(c)] Every further round activates at least one multiply.
\item[(d)] Hence a silenced trail through $\Upd+R$ rounds ($R\ge1$) activates at least $R+2$ multiplies, each of which needs a zero co-operand.  Rigorously, for one-packet messages, $\Pr[\text{silenced trail}]\le 2^{-32k_{\mathrm{msg}}(\delta)}\le2^{-32}$; if the $R+1$ further co-operands are modelled as independent uniform words the bound becomes $2^{-32(R+2)}$, i.e.\ $2^{-96},2^{-128},2^{-160},2^{-192}$ for $R=1,\dots,4$.  Barring exact $64$-bit additive cancellations $\Delta x=-\Delta y$ between two nonzero differences meeting at (A) or (E), every round activates two multiplies and the count is $\ge 2R+1$.
\end{enumerate}
The bound covers the silenced class only.  It says nothing about trails on which some product equality is a coincidence $a'H'=aH$ with both operands differing, nor about trails on which the multipliers do differ but the difference never reaches lane $0$ or cancels inside $\tau$; the observed $R=1$ collisions are of the latter kind.
\end{lemma}
\begin{proof}
(a) If $\lo(\delta_i)\ne0$ the operand $\lo(v_{1,i})$ of $M_{0,i}$ differs; otherwise $c=0$ and $\hi(\delta_i)\ne0$, so the operand $\hi(v_{1,i})$ of $M_{1,i}$ differs (Lemma~\ref{lem:onestep}(a)); $v_0$ is not modified before (B), (D), so the co-operands are equal in both executions.  The co-operands of different lanes depend on different key words, and inside a lane $H_i$, $L_i$ on disjoint halves.
(b) After the message $\Upd$, $v_0$ differs in some lane of every pair $P$ meeting $J$: after (E), $v_0=(v_0+m_1)+\Zip(v_{1,A})$ with $v_0+m_1$ equal and $\Zip(v_{1,A})\ne\Zip(v'_{1,A})$, since $\Zip$ is a bijection of the pair and $v_{1,A}$ differs in lane $i\in J\cap P$.  Let $a$ be such a lane.  In round~1, if $\hi(v_{0,a})$ differs then $M_{0,a}$ is active; else $\lo(v_{0,a})$ differs, so $\lo(v_{0,a}+m_{1,a})$ differs ($m_1$ equal) and $M_{1,a}$ is active.  If $J\subseteq P$, the other pair carries no difference before round~1, and after (A) $v_{1,a\oplus2}=v_{1,a\oplus2}+m_{0,a\oplus2}+\sigma(v_{0,a})$ differs, so $M_{0,a\oplus2}$ or $M_{1,a\oplus2}$ is active; if $J$ meets both pairs, each pair has such a lane $a$.
(c) (A) is a bijection, so after it the states differ in some $v_{0,i}$ (untouched by (A)) or $v_{1,i}$; as in (b) this activates a multiply of lane $i$.
(d) is the sum; the cancellation remark: if $v_0$ is equal in a pair before a round, the pair's $v_0$ differs after it unless it has no difference at all after (A); if $v_0$ differs in a pair, the other pair receives $\sigma$ of it at (A), and only an exact cancellation with an existing $v_1$ difference can leave that pair inactive.
\end{proof}
\noindent\emph{Checked.}  Silenced message Updates were sampled directly in the key subspaces of Lemma~\ref{lem:onestep} (\texttt{cond 16}, $2^{16}$ keys per cell, $20$ cells): with $\hi(k_i)=\hi(c_{0,i})$ and $\delta=1$, with $\lo(k_i)=\lo(c_{0,i})\oplus(-\lo(c_{1,i}))$ and $\delta=2^{32}$, and with both constraints and a random $\delta$, all eight multipliers were equal after the message Update and the difference was confined to $(v_0,v_1)$ of the lane's pair for $65536/65536$ keys; the minimum number of active multiplies in round~$1$ was $3$ ($6$ for the doubly constrained cell), the minimum per round for rounds $2,3,4$ was $4$--$8$, and the minimum cumulative count after $1,2,3,4$ rounds was $4,8,16,24$ (bound: $3,4,5,6$).  No silenced multiply occurred in any round (expected $2^{-32}$ per active multiply).  Unconditioned trails (\texttt{active 16}: all $256$ single-bit and $14$ word-level differences, $2^{16}$ keys each, $32$~B): the minimum cumulative number of active multiplies after the message Update and $1,2,3,4$ rounds was $1,3,7,15,23$ (the round-$1$ minimum $3$ is attained by $76$ of the $256$ bit positions); $0$ silenced multiplies, $0$ product coincidences and $0$ zero operands among $1.4\cdot10^9$ operand draws (expected $0.33$).  The $R=1$ collisions of the lane-$3$ bit-$0$ difference (\texttt{r1coll 20}: $1044491$ of $2^{20}$ keys) all have the four lane-$0$ words equal and $m_{0,3}$ changed, i.e.\ none is a silenced trail; the two $R=2$ collisions in $2^{20}$ keys have distinct lane-$0$ states and are cancellations inside $\tau$.

\begin{lemma}[where a universality proof stops]\label{lem:stop}
Fix $R$ and $M\ne M'$ and let $f(k)=\mathrm{HH}_R(k,M)-\mathrm{HH}_R(k,M')\in\mathbb Z/2^{64}$.  A universality bound $\Pr_k[f(k)=0]\le\varepsilon$ in the style of polynomial hashing needs (P1) $f\not\equiv0$ and (P2) a bound on $|f^{-1}(0)|$ from the algebraic form of $f$.
For $R=0$ and differences confined to lanes $2,3$, (P1) fails (Lemma~\ref{lem:r0}).  For every $R\ge0$, (P2) fails at the first active multiply, for three reasons.
(i) $f$ is not a polynomial over $\mathbb Z/2^{64}$: it contains $\oplus$ with key-dependent words, the splits $\lo,\hi$, and the byte permutations $\Zip$.  Read over $\mathrm{GF}(2)$, its coordinates are Boolean functions of degree up to $64$ (the bits of a $32\times32$ product have algebraic degree increasing with the position), and the only degree bound, $\Pr[g=0]\le1-2^{-\deg g}$ for $g\ne0$, is vacuous.
(ii) Root counting fails in $\mathbb Z/2^{64}$ even for polynomials: $2^{63}X$ has degree $1$ and $2^{63}$ roots (all even $X$); $X^2$ has $2^{32}$ roots; $(2^{32}X)(2^{32}Y)$ vanishes identically.  The multiplies of HighwayHash are bilinear forms in key-dependent halves of exactly this kind.
(iii) The assumption that would close the gap is that the products $a_tH_t$ along the trail (or at least the words $\Delta_t=(m\oplus a_t'H_t')-(m\oplus a_tH_t)$ they contribute to $f$) are independent uniform and independent of the rest of $f$; then $\Pr[f=0]=2^{-64}$ at once.  It is not available: by Lemma~\ref{lem:onestep}(b) $a_t'H_t-a_tH_t=(a_t'-a_t)H_t$ exactly, an integer of magnitude $<2^{32}|a_t'-a_t|$, so $\Delta_t$ is confined to the low $32+\lceil\log_2|a_t'-a_t|\rceil$ bits up to a carry chain of geometric length (for $\delta=+1$ in lane $3$, $2^{20}$ keys, the XOR-difference of $m_{0,3}$ lies below bit $33$ for $75.0\%$ of the keys and below bit $40$ for $99.80\%$; its bytes $0..7$ differ with frequencies $0.996,0.996,0.996,0.996,0.500,0.002,0,0$); a single product of uniform halves is not uniform ($\Pr[\text{bit }63=1]=\tfrac12-\tfrac12\ln2\approx0.1534$, measured $0.1532$ on $2^{20}$ pairs; $\Pr[\text{bit }0=1]=\tfrac14$, measured $0.2496$; and $a'h-ah=(a'-a)h$ held as integers in $2^{20}/2^{20}$ draws); and the operands of successive multiplies are functions of the same key words ($H_i$ and the carry $c$ are both functions of $\hi(k_i)$).  For $R\ge1$ the exact-difference identity itself is lost: by Lemma~\ref{lem:silenced}(b) the round-1 multiplies of lane $a$ have both operands differing, and $a'H'-aH=(a'-a)H'+a(H'-H)$ carries no structure that bounds $\Pr[a'H'=aH]$.
\end{lemma}

\section*{HighwayHash-64 with one 32-byte packet and one finalization round}
\paragraph{Setting.} Key $k=(k_0,\dots,k_3)$ uniform in $(\mathbb Z/2^{64})^4$; $m=(m_0,\dots,m_3)$ one packet; $R=1$; $H_1(m)$ the lane-0 output; $C0_i,C1_i$ the public constants; all arithmetic mod $2^{64}$; $x.b_j$ = byte $j$; $\mathrm{lo},\mathrm{hi}$ = 32-bit halves; $\mathrm{sw}$ swaps them; $f_0(x,y)=[x.b_3,y.b_4,x.b_2,x.b_5,y.b_6,x.b_1,y.b_7,x.b_0]$, $f_1(x,y)=[y.b_3,x.b_4,y.b_2,y.b_5,y.b_1,x.b_6,y.b_0,x.b_7]$.
 egin{lemma}[closed form] With $A_i=(C1_i\oplus\mathrm{sw}(k_i))+C0_i+m_i$, $B_i=(C0_i\oplus k_i)+C1_i$, $M0_i=C0_i\oplus(\mathrm{lo}A_i\cdot\mathrm{hi}(C0_i\oplus k_i))$, $M1_i=C1_i\oplus(\mathrm{lo}B_i\cdot\mathrm{hi}A_i)$, $X_0=B_0+f_0(A_0,A_1)$, $X_1=B_1+f_1(A_0,A_1)$, $Z_2=B_2+f_0(A_2,A_3)$, $Z_3=B_3+f_1(A_2,A_3)$, $Y_0=A_0+f_0(X_0,X_1)$, $Y_1=A_1+f_1(X_0,X_1)$, $U_0=Y_0+M0_0+\mathrm{sw}(Z_2)$, $W_0=X_0+M1_0$, $T=Y_1+M0_1$, $U_1=T+\mathrm{sw}(Z_3)$, $W_1=X_1+M1_1$, $a=W_0+f_0(U_0,U_1)$, $b=W_1+f_1(U_0,U_1)$, $v=U_0+f_0(a,b)$:
$H_1(m)=a+v+[M0_0\oplus(\mathrm{lo}U_0\cdot\mathrm{hi}X_0)]+[M1_0\oplus(\mathrm{lo}W_0\cdot\mathrm{hi}U_0)]$. \end{lemma}
A difference in $A_3$ bytes $\{0,1,2,3,5\}$ or $A_2$ bytes $\{4,6,7\}$ leaves $Z_2$, $U_0$ and both multiply terms unchanged, so $H_1'-H_1=(a'-a)+(v'-v)$ depends only on $(A_2,A_3,B_3,T,U_0,W_0,W_1)$; treating these as free words gives the relaxed model on which z3 certificates are sound for every key.
 egin{lemma}[slice] If for every fixing of the other key bits $Q\equiv\varphi(\kappa)+e(\kappa)\pmod{256}$ with $\varphi$ a bijection of one key byte $\kappa$ and $e(\kappa)\in\{0..r\}$, then $\Pr[Q=v]\le(r+1)/256$, exactly $1/256$ if $r=0$.\end{lemma}
